CREATE   VIEW dbo.[Production_Product] AS SELECT CAST([ProductID] AS int) AS [ProductID], CAST([Name] AS VARCHAR(50)) AS [Name], CAST([ProductNumber] AS VARCHAR(25)) AS [ProductNumber], CAST([MakeFlag] AS bit) AS [MakeFlag], CAST([FinishedGoodsFlag] AS bit) AS [FinishedGoodsFlag], CAST([Color] AS VARCHAR(15)) AS [Color], CAST([SafetyStockLevel] AS smallint) AS [SafetyStockLevel], CAST([ReorderPoint] AS smallint) AS [ReorderPoint], CAST([StandardCost] AS money) AS [StandardCost], CAST([ListPrice] AS money) AS [ListPrice], CAST([Size] AS VARCHAR(5)) AS [Size], CAST([SizeUnitMeasureCode] AS nchar(3)) AS [SizeUnitMeasureCode], CAST([WeightUnitMeasureCode] AS nchar(3)) AS [WeightUnitMeasureCode], CAST([Weight] AS decimal(8,2)) AS [Weight], CAST([DaysToManufacture] AS int) AS [DaysToManufacture], CAST([ProductLine] AS nchar(2)) AS [ProductLine], CAST([Class] AS nchar(2)) AS [Class], CAST([Style] AS nchar(2)) AS [Style], CAST([ProductSubcategoryID] AS int) AS [ProductSubcategoryID], CAST([ProductModelID] AS int) AS [ProductModelID], CAST([SellStartDate] AS datetime2(6)) AS [SellStartDate], CAST([SellEndDate] AS datetime2(6)) AS [SellEndDate], CAST([DiscontinuedDate] AS datetime2(6)) AS [DiscontinuedDate], CAST([rowguid] AS uniqueidentifier) AS [rowguid], CAST([ModifiedDate] AS datetime2(6)) AS [ModifiedDate] FROM [lh_bronze].[bronze].[Production_Product];

GO